import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.mzJ8I8R4.js";const g=JSON.parse('{"title":"接入 agent","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent.md","filePath":"guide/agent.md"}'),o={name:"guide/agent.md"};function l(n,e,d,p,h,r){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="接入-agent" tabindex="-1">接入 agent <a class="header-anchor" href="#接入-agent" aria-label="Permalink to &quot;接入 agent&quot;">​</a></h1><p>agent 指 Claude Code、Codex 这类能在电脑上执行命令的 AI 助手。接入 NextTodo 后，可以让它拆分计划、添加事项、设置先后、勾选完成，就像在 App 里操作一样，改动会同步到所有设备。</p><p>agent 有两种接入方式，任选其一：</p><ul><li><strong>MCP</strong>：agent 直接连 NextTodo，配置一次即可。</li><li><strong>命令行</strong>：先装好命令行 <code>nexttodo</code>，agent 通过它读写待办；再装上 skill，agent 就知道怎么用。</li></ul><h2 id="_1-生成令牌" tabindex="-1">1. 生成令牌 <a class="header-anchor" href="#_1-生成令牌" aria-label="Permalink to &quot;1. 生成令牌&quot;">​</a></h2><p>令牌是给 agent 用的通行证，每个 agent 用一个，方便分清谁做了什么。</p><ol><li>打开“设置”，在“令牌”一组点“生成令牌”。</li><li>名称写 agent 的名字，比如“Claude Code”，它会显示在这个 agent 做的改动旁边。</li><li>选“读写”或“只读”，点“生成”。</li></ol><p>令牌只显示这一次。页面上同时给出已经填好服务器地址和令牌的 Claude Code、Codex 配置和命令行环境变量，点右侧的按钮复制即可。不再使用时，在“令牌”一组里删除它，用这个令牌的 agent 随即失去访问权限。</p><h2 id="cli" tabindex="-1">2. 安装命令行 <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;2. 安装命令行 {#cli}&quot;">​</a></h2><p>用 MCP 连接服务器的，可以跳过这一步。</p><p><strong>用桌面 App 安装（macOS 和 Windows）</strong>：</p><ol><li>打开“设置”，在“命令行”一组点“安装”。</li><li>macOS 上可能会弹出系统的密码框，输入登录密码确认。</li><li>新打开一个终端窗口，运行 <code>nexttodo --version</code>，显示的版本应和“设置 → 关于”里的 App 版本相同。</li></ol><p>版本不同，说明以前用别的方式装过命令行，终端用的是那一个。查看终端实际用的是哪个：macOS 上运行 <code>which -a nexttodo</code>，Windows 上运行 <code>where.exe nexttodo</code>（PowerShell 和命令提示符都适用），第一行就是。确认它是以前自己装的 NextTodo 命令行（比如用 <code>cargo install</code> 或安装脚本装的）后，按原来的方式卸载或删掉它；macOS 上也可以在 shell 配置文件里把 <code>/usr/local/bin</code> 排到它所在的目录前面。</p><p>App 更新时，命令行会一起更新。macOS 上要先把 App 移到“应用程序”文件夹，见<a href="./install#macos">下载和安装</a>。</p><p><strong>用安装脚本（macOS 和 Linux）</strong>：在终端里运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://juniexd.github.io/NextTodo/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>脚本把最新版装进 <code>~/.local/bin</code>。这个目录不在 <code>PATH</code> 里时，脚本会给出要加进 shell 配置文件的一行。以后服务器升级了，再运行一次即可更新。</p><p><strong>手动下载</strong>：从 <a href="https://github.com/JunieXD/NextTodo/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> 下载对应平台的文件，改名为 <code>nexttodo</code>（Windows 上是 <code>nexttodo.exe</code>），放进 <code>PATH</code> 里的目录。</p><h2 id="_3-连接" tabindex="-1">3. 连接 <a class="header-anchor" href="#_3-连接" aria-label="Permalink to &quot;3. 连接&quot;">​</a></h2><h3 id="连接服务器时" tabindex="-1">连接服务器时 <a class="header-anchor" href="#连接服务器时" aria-label="Permalink to &quot;连接服务器时&quot;">​</a></h3><ul><li><p><strong>Claude Code</strong>：复制令牌页上 Claude Code 的那条命令，在终端里运行。</p></li><li><p><strong>Codex</strong>：把令牌页上 Codex 的配置加进 <code>~/.codex/config.toml</code>，再按页面上的写法设置环境变量。</p></li><li><p><strong>命令行</strong>：登录后，把 skill 装给 agent：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nexttodo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://todo.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Claude Code&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nexttodo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nexttodo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span></span></code></pre></div><p><code>login</code> 会要求输入用户名和密码，并为这台电脑生成一个令牌；<code>next</code> 列出现在能做的事，能看到就说明连上了。</p></li></ul><h3 id="在本机使用时" tabindex="-1">在本机使用时 <a class="header-anchor" href="#在本机使用时" aria-label="Permalink to &quot;在本机使用时&quot;">​</a></h3><p>App 在本机运行时，每次启动的地址都不同，所以 agent 要经过命令行连接：</p><ol><li>先<a href="#cli">安装命令行</a>。</li><li>生成令牌后，按令牌页给出的写法配置 Claude Code 或 Codex，或者设置环境变量 <code>NEXTTODO_URL=local</code> 和 <code>NEXTTODO_TOKEN</code>。</li></ol><p>只在电脑上、NextTodo 运行时可用（关掉窗口也算在运行）。Android 的本机模式不能接入 agent。</p><h2 id="撤销-agent-的改动" tabindex="-1">撤销 agent 的改动 <a class="header-anchor" href="#撤销-agent-的改动" aria-label="Permalink to &quot;撤销 agent 的改动&quot;">​</a></h2><p>agent 改完后，App 的提示条会写明它做了什么，比如“Claude Code 在‘求职’中添加了 4 项”，点“撤销”即可撤回。</p><p>每次改动都有记录。错过了提示条，可以让 agent 运行 <code>nexttodo log</code> 查看最近的改动，再用 <code>nexttodo undo &lt;批次&gt;</code> 撤销其中一次。</p><p>更完整的说明（工具列表、计划的格式）见开发文档 <a href="https://github.com/JunieXD/NextTodo/blob/main/docs/agent.md" target="_blank" rel="noreferrer">agent 接入</a>。</p>`,29)])])}const k=a(o,[["render",l]]);export{g as __pageData,k as default};
